#include <cstdio>
#include <cstring>
#include <cmath>
#include <cstdlib>
#include <vector>
#include <string>
#include <algorithm>
#include <queue>
#include <stack>
#include <deque>
#include <map>
#include <set>
#include <unordered_map>
#include <unordered_set>
#include <functional>
#include <numeric>
#include <sstream>
#include <iostream>
using namespace std;
int main(){int n;scanf("%d",&n);vector<long long>a(n);
for(int i=0;i<n;++i)scanf("%lld",&a[i]);
sort(a.rbegin(),a.rend());
for(int i=0;i+2<n;++i)
if(a[i]<a[i+1]+a[i+2]){printf("%lld\n",a[i]+a[i+1]+a[i+2]);return 0;}
printf("0\n");return 0;}

